import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Exercises SERVICE scope boundaries with a real parsed query and a deterministic in-process service. The service
 * records every incoming binding so these tests assert the binding environment directly instead of relying on a
 * request-counting implementation detail.
 */
public class MemoryServiceInvocationScopeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI A = VF.createIRI("urn:scope:a");
	private static final IRI B = VF.createIRI("urn:scope:b");
	private static final IRI C = VF.createIRI("urn:scope:c");
	private static final Literal SEVEN = VF.createLiteral(7);
	private static final Literal NINE = VF.createLiteral(9);
	private static final String PREFIX = "PREFIX : <urn:scope:> ";
	private static final String SERVICE = "SERVICE <urn:scope:service>";

	private SailRepository repository;
	private RecordingService service;

	@BeforeEach
	public void setUp() {
		service = new RecordingService();
		repository = new SailRepository(new MemoryStore());
		repository.setFederatedServiceResolver(new RecordingServiceResolver(service));
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	@Test
	public void localSubqueryServiceReceivesNoOuterXBindingAndCrossProductsValues() {
		List<BindingSet> rows = evaluate(PREFIX
				+ "SELECT ?x ?v WHERE { VALUES ?x { :a :b } "
				+ "{ SELECT ?v WHERE { " + SERVICE + " { ?x :p ?v } } } }");

		assertRows(rows, Set.of(rowKey(A, SEVEN), rowKey(A, NINE), rowKey(B, SEVEN), rowKey(B, NINE)));
		assertFalse(service.observedBindings().isEmpty(), "the parsed subquery must invoke the SERVICE resolver");
		assertTrue(service.observedBindings().stream().allMatch(binding -> !binding.hasBinding("x")),
				"the local subquery does not project the outer ?x, so SERVICE receives empty input mappings");
	}

	@Test
	public void nestedUnionFilterExistsPreservesIndependentRows() {
		List<BindingSet> rows = evaluate(PREFIX
				+ "SELECT ?x ?v WHERE { VALUES ?x { :a :b } "
				+ "{ { " + SERVICE + " { ?x :p ?v } } "
				+ "UNION { FILTER EXISTS { " + SERVICE + " { ?x :p ?v } } } } }");

		assertRows(rows, Set.of(rowKey(A, SEVEN), rowKey(A, null), rowKey(B, null)));
	}

	@Test
	public void nestedUnionFilterNotExistsKeepsOnlyDirectServiceRows() {
		List<BindingSet> rows = evaluate(PREFIX
				+ "SELECT ?x ?v WHERE { VALUES ?x { :a :b } "
				+ "{ { " + SERVICE + " { ?x :p ?v } } "
				+ "UNION { FILTER NOT EXISTS { " + SERVICE + " { ?x :p ?v } } } } }");

		assertRows(rows, Set.of(rowKey(A, SEVEN)));
	}

	@Test
	public void directFilterExistsUsesOuterValuesAsServiceConstraints() {
		List<BindingSet> rows = evaluate(PREFIX
				+ "SELECT ?x WHERE { VALUES ?x { :a :b } "
				+ "FILTER EXISTS { " + SERVICE + " { ?x :p ?v } } }");

		assertRows(rows, Set.of(rowKey(A, null)));
	}

	@Test
	public void directFilterNotExistsUsesOuterValuesAsServiceConstraints() {
		List<BindingSet> rows = evaluate(PREFIX
				+ "SELECT ?x WHERE { VALUES ?x { :a :b } "
				+ "FILTER NOT EXISTS { " + SERVICE + " { ?x :p ?v } } }");

		assertRows(rows, Set.of(rowKey(B, null)));
	}

	private List<BindingSet> evaluate(String query) {
		try (RepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static void assertRows(List<BindingSet> rows, Set<String> expected) {
		Set<String> actual = rows.stream()
				.map(row -> rowKey(row.getValue("x"), row.getValue("v")))
				.collect(Collectors.toCollection(HashSet::new));
		assertEquals(expected.size(), rows.size(), "unexpected row multiplicity");
		assertEquals(expected, actual);
	}

	private static String rowKey(Value x, Value v) {
		return (x == null ? "<unbound>" : x.stringValue()) + "|" + (v == null ? "<unbound>" : v.stringValue());
	}

	private static final class RecordingServiceResolver implements FederatedServiceResolver {

		private final RecordingService service;

		private RecordingServiceResolver(RecordingService service) {
			this.service = service;
		}

		@Override
		public FederatedService getService(String serviceUrl) {
			return service;
		}
	}

	private static final class RecordingService implements FederatedService {

		private static final List<RemoteRow> REMOTE_ROWS = List.of(new RemoteRow(A, SEVEN), new RemoteRow(C, NINE));
		private final List<BindingSet> observedBindings = new CopyOnWriteArrayList<>();

		private List<BindingSet> observedBindings() {
			return List.copyOf(observedBindings);
		}

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseUri) {
			record(bindings);
			return !matchingRows(bindings).isEmpty();
		}

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			record(bindings);
			return new CloseableIteratorIteration<>(matchingRows(bindings).iterator());
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service,
				CloseableIteration<BindingSet> bindings, String baseUri) {
			List<BindingSet> inputMappings = new ArrayList<>();
			try {
				while (bindings.hasNext()) {
					BindingSet input = copy(bindings.next());
					record(input);
					inputMappings.add(input);
				}
			} finally {
				bindings.close();
			}

			List<BindingSet> results = new ArrayList<>();
			for (BindingSet input : inputMappings) {
				results.addAll(matchingRows(input));
			}
			return new CloseableIteratorIteration<>(results.iterator());
		}

		@Override
		public boolean isInitialized() {
			return true;
		}

		@Override
		public void initialize() {
			// Nothing to initialize for the in-process fixture.
		}

		@Override
		public void shutdown() {
			// Nothing to shut down for the in-process fixture.
		}

		private void record(BindingSet bindings) {
			observedBindings.add(copy(bindings));
		}

		private static BindingSet copy(BindingSet bindings) {
			return new QueryBindingSet(bindings);
		}

		private static List<BindingSet> matchingRows(BindingSet bindings) {
			Value requestedSubject = bindings.getValue("x");
			List<BindingSet> results = new ArrayList<>();
			for (RemoteRow row : REMOTE_ROWS) {
				if (requestedSubject != null && !requestedSubject.equals(row.subject())) {
					continue;
				}

				QueryBindingSet result = new QueryBindingSet(bindings);
				result.setBinding("x", row.subject());
				result.setBinding("v", row.value());
				results.add(result);
			}
			return results;
		}
	}

	private record RemoteRow(IRI subject, Literal value) {
	}
}
